"""Local systems of the small fake/actual models: is J(A)_m generated by width powers (b0 = 1) or by width powers +
column-family pullbacks (b0 = 2, 3)?  All ideals are compared in R = Q[x]/(x_i^3) in degree m (cumulative degrees are
not needed for TC(A,m), which depends on J(A)_m only).

Certification (sandwich, as round12 README §4.2(c)): local generators are exact elements of J(A) over Q; dim_p of their
span in R_m is <= dim_Q; dim_Q J(A)_m = N_m - H_A(m) is computed from exact (fmpz) ranks.  So dim_p(local) = dim_Q J(A)_m
proves Loc_m(b0) exactly; a strict inequality mod p is evidence only.
usage: python3 locsys.py model L m bmax
"""
import sys, itertools, time
import numpy as np
from flint import nmod_mat, fmpz_mat
from fplib import *


def reduce_poly(poly):
    """dict exponent->coef in d vars -> reduced (exponents <= 2) using x^3 = x?  NO: in R = S/(x^3) we set x^3 = 0
    (J contains x^3; we work modulo the ideal (x^3), i.e. drop monomials with an exponent >= 3)."""
    return {e: c for e, c in poly.items() if max(e) <= 2 and c}


def lin_power_times(v, p, mono, d):
    """(sum v_x x_x)^p * x^mono, as dict, dropping exponents >= 3."""
    poly = {tuple(mono): 1}
    nz = [(x, vx) for x, vx in enumerate(v) if vx]
    for _ in range(p):
        new = {}
        for e, c in poly.items():
            for x, vx in nz:
                if e[x] >= 2:
                    continue
                e2 = list(e); e2[x] += 1; e2 = tuple(e2)
                new[e2] = new.get(e2, 0) + c * vx
        poly = {e: c for e, c in new.items() if c}
    return poly


def jdeg_basis(B, e):
    """basis (exact ints) of J(B)_e for a finite B subset Z^b: degree-e forms f with f|_B in Poly_{<e}|_B.
    Returns list of dicts exponent->int."""
    b = len(B[0])
    mons_e = [m for m in itertools.product(range(e + 1), repeat=b) if sum(m) == e]
    mons_l = [m for m in itertools.product(range(e), repeat=b) if sum(m) < e]
    Bo = np.array(B, dtype=object)

    def col(m):
        c = np.ones(len(B), dtype=object)
        for q, mq in enumerate(m):
            if mq:
                c = c * Bo[:, q] ** mq
        return c
    Mcols = [col(m) for m in mons_e] + [col(m) for m in mons_l]
    Mz = fmpz_mat(len(B), len(Mcols), [int(Mcols[c][r]) for r in range(len(B)) for c in range(len(Mcols))])
    K, nul = Mz.nullspace()
    out = []
    for k in range(nul):
        f = {}
        for i, m in enumerate(mons_e):
            v = int(K[i, k])
            if v:
                f[m] = v
        if f:
            out.append(f)
    return out


def main():
    name, L, m, bmax = sys.argv[1], int(sys.argv[2]), int(sys.argv[3]), int(sys.argv[4])
    M, pats = MODELS[name]()
    A = box(M, pats, L)
    d = M - 1
    Aarr = np.array(A, dtype=np.int64)
    t0 = time.time()
    monos = reduced_monomials(d, m)
    idx = {a: i for i, a in enumerate(monos)}
    # exact H_A(m) and dim J(A)_m in R
    low = []
    for e in range(m):
        low += reduced_monomials(d, e)
    El = eval_matrix(A, low)
    Ef = eval_matrix(A, low + monos)
    rl = fmpz_mat(El.shape[0], El.shape[1], [int(x) for x in El.flatten()]).rank()
    rf = fmpz_mat(Ef.shape[0], Ef.shape[1], [int(x) for x in Ef.flatten()]).rank()
    HAm = rf - rl
    dimJ = len(monos) - HAm
    print(f'{name} L={L} m={m}: |A|={len(A)} N_m={len(monos)} H_A(m)={HAm} (exact) dim J(A)_m={dimJ}  ({time.time()-t0:.0f}s)',
          flush=True)
    rows = []

    def add(poly):
        r = [0] * len(monos)
        for e, c in poly.items():
            r[idx[e]] = int(c) % PR
        rows.append(r)

    def rank_rows():
        if not rows:
            return 0
        return nmod_mat(len(rows), len(monos), [x for r in rows for x in r], PR).rank()
    # b = 1: width powers over primitive v in {-2..2}^d (up to sign) with tau+1 <= m
    dirs = [v for v in itertools.product(range(-2, 3), repeat=d) if any(v) and next(x for x in v if x) > 0]
    D = np.array(dirs, dtype=np.int64)
    ntau = 0
    for s0 in range(0, len(D), 4000):
        vals = Aarr @ D[s0:s0 + 4000].T
        vs = np.sort(vals, axis=0)
        taus = (np.diff(vs, axis=0) != 0).sum(axis=0)
        for v, tau in zip(D[s0:s0 + 4000], taus):
            p = int(tau) + 1
            if p > m:
                continue
            ntau += 1
            for mono in reduced_monomials(d, m - p):
                poly = lin_power_times([int(x) for x in v], p, mono, d)
                if poly:
                    add(poly)
        # compress
        if len(rows) > 3 * len(monos):
            Nn = nmod_mat(len(rows), len(monos), [x for r in rows for x in r], PR).rref()[0]
            rk = Nn.rank()
            rows[:] = [[int(Nn[i, c]) for c in range(len(monos))] for i in range(rk)]
    r1 = rank_rows()
    print(f'  b0=1 (width powers of {ntau} directions in [-2,2]^d): dim_p = {r1}  ->  Loc_m(1) '
          f'{"HOLDS (exact, sandwich)" if r1 == dimJ else "not shown (deficit %d mod p)" % (dimJ - r1)}', flush=True)
    # b = 2..bmax: column families (relative patterns as directions 1_P)
    cols = [tuple(1 if (x + 1) in P else 0 for x in range(d)) for P in pats]
    for b in range(2, bmax + 1):
        for F in itertools.combinations(range(len(cols)), b):
            V = np.array([cols[q] for q in F], dtype=np.int64)
            if np.linalg.matrix_rank(V) < b:
                continue
            B = sorted(set(map(tuple, Aarr @ V.T)))
            for e in range(2, m + 1):
                for f in jdeg_basis(B, e):
                    # pull back f(y), y_q = <v_q, x>, times monomials of degree m - e
                    for mono in reduced_monomials(d, m - e):
                        poly = {}
                        for ex, cf in f.items():
                            part = {tuple(mono): cf}
                            for q, eq in enumerate(ex):
                                for _ in range(eq):
                                    new = {}
                                    for e0, c0 in part.items():
                                        for x in range(d):
                                            if V[q, x] and e0[x] < 2:
                                                e2 = list(e0); e2[x] += 1; e2 = tuple(e2)
                                                new[e2] = new.get(e2, 0) + c0 * int(V[q, x])
                                    part = {k: c for k, c in new.items() if c}
                            for k2, c2 in part.items():
                                poly[k2] = poly.get(k2, 0) + c2
                        poly = {k: c for k, c in poly.items() if c}
                        if poly:
                            add(poly)
            if len(rows) > 3 * len(monos):
                Nn = nmod_mat(len(rows), len(monos), [x for r in rows for x in r], PR).rref()[0]
                rk = Nn.rank()
                rows[:] = [[int(Nn[i, c]) for c in range(len(monos))] for i in range(rk)]
        rb = rank_rows()
        print(f'  b0={b} (widths + column families of size <= {b}): dim_p = {rb}  ->  Loc_m({b}) '
              f'{"HOLDS (exact, sandwich)" if rb == dimJ else "not shown (deficit %d mod p)" % (dimJ - rb)}  '
              f'({time.time()-t0:.0f}s)', flush=True)


if __name__ == '__main__':
    main()
